'use strict';
// Local-only junior React pack. Every definition below has a separate learning goal.
const fs = require('node:fs');
const path = require('node:path');
const dir = path.join(__dirname, 'react-junior');
const tasks = [];
function add(title, category, spec, code, test, options = {}) {
  tasks.push({ title, category, spec, code, test, ...options });
}

add('Repair a batched counter', 'state / debugging',
`Start at 0 in one output. Add three must add exactly 3 in one click; Reset returns to 0. Repair the stale-snapshot bug illustrated by three consecutive setCount(count + 1) calls. Use functional state updates for the three increments; no module-level state. Repeated clicks must accumulate.`,
`const [count,setCount]=useState(0);
return <section><output>{count}</output><button onClick={()=>{setCount(n=>n+1);setCount(n=>n+1);setCount(n=>n+1);}}>Add three</button><button onClick={()=>setCount(0)}>Reset</button></section>;`,
`assert.equal(status(),'0');click('Add three');assert.equal(status(),'3');click('Add three');assert.equal(status(),'6');click('Reset');assert.equal(status(),'0');click('Add three');assert.equal(status(),'3');`);

add('Immutable cart line updates', 'state',
`Props initialItems is an array of {id,name,price,quantity} with integer prices in cents. Keep a local editable cart. Render each item in a listitem with buttons Increase NAME and Decrease NAME. Quantities cannot go below 0; disable Decrease at 0. Each row has an output labelled Quantity NAME. A separate output labelled Total displays cents. Updating one row must preserve others and never mutate initialItems.`,
`const [items,setItems]=useState(()=>initialItems.map(x=>({...x})));
const adjust=(id,step)=>setItems(old=>old.map(x=>x.id===id?{...x,quantity:Math.max(0,x.quantity+step)}:x));
return <section><ul>{items.map(x=><li key={x.id}>{x.name}<output aria-label={'Quantity '+x.name}>{x.quantity}</output><button aria-label={'Increase '+x.name} onClick={()=>adjust(x.id,1)}>+</button><button aria-label={'Decrease '+x.name} disabled={x.quantity===0} onClick={()=>adjust(x.id,-1)}>-</button></li>)}</ul><output aria-label="Total">{items.reduce((sum,x)=>sum+x.price*x.quantity,0)}</output></section>;`,
`const out=n=>view.getByRole('status',{name:n}).textContent;assert.equal(out('Total'),'350');click('Increase Pen');assert.equal(out('Quantity Pen'),'2');assert.equal(out('Quantity Book'),'1');assert.equal(out('Total'),'450');click('Decrease Book');assert.equal(out('Total'),'200');assert.equal(button('Decrease Book').disabled,true);click('Decrease Book');assert.equal(out('Quantity Book'),'0');assert.deepEqual(props.initialItems,[{id:'p',name:'Pen',price:100,quantity:1},{id:'b',name:'Book',price:250,quantity:1}]);`,
{params:'{initialItems=[]}',props:{initialItems:[{id:'p',name:'Pen',price:100,quantity:1},{id:'b',name:'Book',price:250,quantity:1}]},setup:'props.initialItems.forEach(Object.freeze);Object.freeze(props.initialItems);'});

add('Reducer match scoreboard', 'state',
`Build a useReducer scoreboard with Red and Blue scores initially 0. Goal Red / Goal Blue increment that team. Output labelled Score reads RED:BLUE. End match freezes scoring and changes status labelled Match from playing to final. New match resets both scores and resumes play. Disable goal and End match buttons after ending.`,
`const [s,dispatch]=useReducer((s,a)=>a==='reset'?{red:0,blue:0,final:false}:s.final?s:a==='end'?{...s,final:true}:{...s,[a]:s[a]+1},{red:0,blue:0,final:false});
return <section><output aria-label="Score">{s.red}:{s.blue}</output><output aria-label="Match">{s.final?'final':'playing'}</output><button disabled={s.final} onClick={()=>dispatch('red')}>Goal Red</button><button disabled={s.final} onClick={()=>dispatch('blue')}>Goal Blue</button><button disabled={s.final} onClick={()=>dispatch('end')}>End match</button><button onClick={()=>dispatch('reset')}>New match</button></section>;`,
`const out=n=>view.getByRole('status',{name:n}).textContent;assert.equal(out('Score'),'0:0');click('Goal Red');click('Goal Red');click('Goal Blue');assert.equal(out('Score'),'2:1');click('End match');assert.equal(out('Match'),'final');assert.equal(button('Goal Red').disabled,true);assert.equal(button('Goal Blue').disabled,true);assert.equal(button('End match').disabled,true);click('Goal Red');assert.equal(out('Score'),'2:1');click('New match');assert.equal(out('Score'),'0:0');assert.equal(out('Match'),'playing');click('Goal Blue');assert.equal(out('Score'),'0:1');`);

add('Move people between teams', 'state',
`Props people is an ordered array of unique names. Initially all are Available, none Assigned. Use two lists with those accessible names. Each available row has Assign NAME; assigned rows have Return NAME. Moving appends to the destination, removes from source, and cannot create duplicates. Output is assigned count. Preserve the input array.`,
`const [available,setAvailable]=useState(()=>[...people]),[assigned,setAssigned]=useState([]);
const move=(name,assign)=>{if(assign){setAvailable(xs=>xs.filter(x=>x!==name));setAssigned(xs=>xs.includes(name)?xs:[...xs,name]);}else{setAssigned(xs=>xs.filter(x=>x!==name));setAvailable(xs=>xs.includes(name)?xs:[...xs,name]);}};
return <section><ul aria-label="Available">{available.map(x=><li key={x}>{x}<button aria-label={'Assign '+x} onClick={()=>move(x,true)}>Assign</button></li>)}</ul><ul aria-label="Assigned">{assigned.map(x=><li key={x}>{x}<button aria-label={'Return '+x} onClick={()=>move(x,false)}>Return</button></li>)}</ul><output>{assigned.length}</output></section>;`,
`const names=n=>within(view.getByRole('list',{name:n})).queryAllByRole('listitem').map(x=>x.firstChild.textContent);assert.deepEqual(names('Available'),['Ada','Bo','Cy']);assert.equal(status(),'0');click('Assign Bo');click('Assign Ada');assert.deepEqual(names('Assigned'),['Bo','Ada']);assert.deepEqual(names('Available'),['Cy']);assert.equal(status(),'2');click('Return Bo');assert.deepEqual(names('Available'),['Cy','Bo']);assert.deepEqual(names('Assigned'),['Ada']);click('Assign Bo');assert.deepEqual(names('Assigned'),['Ada','Bo']);assert.deepEqual(props.people,['Ada','Bo','Cy']);`,
{params:'{people=[]}',props:{people:['Ada','Bo','Cy']},setup:'Object.freeze(props.people);'});

add('Update nested notification preferences', 'state / debugging',
`Initial preferences: email enabled, SMS disabled, theme light. Expose Email and SMS checkboxes, a Theme select (light/dark), and Reset. Output is JSON with shape {notifications:{email:boolean,sms:boolean},theme:string}. Changing one nested property must preserve its sibling and the theme. Fix the common replacement bug setPrefs({notifications:{email:checked}}).`,
`const initial=()=>({notifications:{email:true,sms:false},theme:'light'});
const [prefs,setPrefs]=useState(initial);
return <section>{['email','sms'].map(key=><label key={key}>{key==='email'?'Email':'SMS'}<input type="checkbox" checked={prefs.notifications[key]} onChange={e=>{const checked=e.target.checked;setPrefs(p=>({...p,notifications:{...p.notifications,[key]:checked}}));}}/></label>)}<label>Theme<select value={prefs.theme} onChange={e=>{const theme=e.target.value;setPrefs(p=>({...p,theme}));}}><option>light</option><option>dark</option></select></label><button onClick={()=>setPrefs(initial())}>Reset</button><output>{JSON.stringify(prefs)}</output></section>;`,
`change('Theme','dark');fireEvent.click(field('SMS'));fireEvent.click(field('Email'));assert.deepEqual(JSON.parse(status()),{notifications:{email:false,sms:true},theme:'dark'});fireEvent.click(field('Email'));assert.deepEqual(JSON.parse(status()),{notifications:{email:true,sms:true},theme:'dark'});click('Reset');assert.deepEqual(JSON.parse(status()),{notifications:{email:true,sms:false},theme:'light'});assert.equal(field('SMS').checked,false);`);

add('Three-state stable sorting', 'state',
`Variant of a sortable list: Score cycles original -> ascending -> descending -> original. Props rows are {id,name,score}. Render names in listitems. Ties retain original order even descending; do not mutate props. One output says original/ascending/descending. New rows from a rerender must be reflected without resetting the active sort mode.`,
`const [mode,setMode]=useState(0);
const ordered=rows.map((row,index)=>({row,index}));if(mode)ordered.sort((a,b)=>(mode===1?a.row.score-b.row.score:b.row.score-a.row.score)||a.index-b.index);
return <section><button onClick={()=>setMode(m=>(m+1)%3)}>Score</button><output>{['original','ascending','descending'][mode]}</output><ul>{ordered.map(({row})=><li key={row.id}>{row.name}</li>)}</ul></section>;`,
`const names=()=>view.queryAllByRole('listitem').map(x=>x.textContent);assert.deepEqual(names(),['Zed','Ada','Bo']);click('Score');assert.equal(status(),'ascending');assert.deepEqual(names(),['Ada','Bo','Zed']);click('Score');assert.deepEqual(names(),['Zed','Ada','Bo']);assert.equal(status(),'descending');click('Score');assert.equal(status(),'original');assert.deepEqual(names(),['Zed','Ada','Bo']);click('Score');view.rerender(React.createElement(Component,{rows:[{id:'x',name:'Only',score:4}]}));assert.equal(status(),'ascending');assert.deepEqual(names(),['Only']);assert.equal(props.rows[0].name,'Zed');`,
{params:'{rows=[]}',props:{rows:[{id:'z',name:'Zed',score:5},{id:'a',name:'Ada',score:2},{id:'b',name:'Bo',score:2}]},setup:'props.rows.forEach(Object.freeze);Object.freeze(props.rows);'});

add('Split a bill without redundant state', 'state / derived data',
`Controlled number inputs Bill (initial 0), Tip percent (initial 10), and People (initial 1). Output per-person amount to two decimals: bill*(1+tip/100)/people. Valid bill >=0, tip 0..100, people positive integer; all fields required and finite. Invalid or blank fields show em dash (—), never Infinity/NaN. Derive the output rather than synchronize another state variable.`,
`const [bill,setBill]=useState('0'),[tip,setTip]=useState('10'),[people,setPeople]=useState('1');
const b=Number(bill),t=Number(tip),p=Number(people);const valid=[bill,tip,people].every(x=>x.trim()!=='')&&[b,t,p].every(Number.isFinite)&&b>=0&&t>=0&&t<=100&&p>0&&Number.isInteger(p);
return <section><label>Bill<input type="number" value={bill} onChange={e=>setBill(e.target.value)}/></label><label>Tip percent<input type="number" value={tip} onChange={e=>setTip(e.target.value)}/></label><label>People<input type="number" value={people} onChange={e=>setPeople(e.target.value)}/></label><output>{valid?(b*(1+t/100)/p).toFixed(2):'—'}</output></section>;`,
`assert.equal(status(),'0.00');change('Bill','90');change('People','3');assert.equal(status(),'33.00');change('Tip percent','20');assert.equal(status(),'36.00');for(const value of ['0','-1','1.5','']){change('People',value);assert.equal(status(),'—');}change('People','2');change('Bill','-5');assert.equal(status(),'—');change('Bill','100');change('Tip percent','101');assert.equal(status(),'—');change('Tip percent','0');assert.equal(status(),'50.00');`);

add('Bidirectional temperature inputs', 'state / derived data',
`Celsius and Fahrenheit are controlled text inputs. Initially both empty. The last edited field preserves the exact raw string; derive the other with (C*9/5+32) or ((F-32)*5/9), rounded to one decimal with toFixed(1). Blank, whitespace, or nonfinite/non-numeric input clears the derived field without changing the raw source. Avoid feedback-loop effects and permit negative values.`,
`const [entry,setEntry]=useState({scale:'c',raw:''});const number=Number(entry.raw);const valid=entry.raw.trim()!==''&&Number.isFinite(number);const other=valid?(entry.scale==='c'?number*9/5+32:(number-32)*5/9).toFixed(1):'';
return <section><label>Celsius<input value={entry.scale==='c'?entry.raw:other} onChange={e=>setEntry({scale:'c',raw:e.target.value})}/></label><label>Fahrenheit<input value={entry.scale==='f'?entry.raw:other} onChange={e=>setEntry({scale:'f',raw:e.target.value})}/></label></section>;`,
`assert.equal(field('Celsius').value,'');assert.equal(field('Fahrenheit').value,'');change('Celsius','100');assert.equal(field('Fahrenheit').value,'212.0');change('Fahrenheit','32');assert.equal(field('Celsius').value,'0.0');assert.equal(field('Fahrenheit').value,'32');change('Celsius','-40');assert.equal(field('Fahrenheit').value,'-40.0');change('Celsius','oops');assert.equal(field('Celsius').value,'oops');assert.equal(field('Fahrenheit').value,'');change('Fahrenheit','50');change('Fahrenheit','');assert.equal(field('Celsius').value,'');change('Celsius','Infinity');assert.equal(field('Fahrenheit').value,'');`);

add('Profile form with a saved baseline', 'forms',
`Props initialName (default Ada) initializes a saved baseline once per mount. Name input edits a draft. Save is disabled if trim is empty or equals saved name; Discard is disabled only when raw draft equals saved name. Save commits trimmed name, normalizes the field, and displays it in output. Discard restores the latest saved baseline, not the initial prop.`,
`const [saved,setSaved]=useState(initialName),[draft,setDraft]=useState(initialName);
return <form onSubmit={e=>{e.preventDefault();if(draft.trim()&&draft.trim()!==saved){setSaved(draft.trim());setDraft(draft.trim());}}}><label>Name<input value={draft} onChange={e=>setDraft(e.target.value)}/></label><button disabled={!draft.trim()||draft.trim()===saved}>Save</button><button type="button" disabled={draft===saved} onClick={()=>setDraft(saved)}>Discard</button><output>{saved}</output></form>;`,
`assert.equal(button('Save').disabled,true);assert.equal(button('Discard').disabled,true);change('Name','   ');assert.equal(button('Save').disabled,true);click('Discard');assert.equal(field('Name').value,'Ada');change('Name',' Bo ');click('Save');assert.equal(status(),'Bo');assert.equal(field('Name').value,'Bo');change('Name','Cy');click('Discard');assert.equal(field('Name').value,'Bo');change('Name',' Bo ');assert.equal(button('Save').disabled,true);assert.equal(button('Discard').disabled,false);`,
{params:"{initialName='Ada'}"});

add('Password confirmation with touched errors', 'forms / a11y',
`Password and Confirm are controlled password inputs. Password must be >=8 characters; Confirm must exactly match. Show each error only after that field blurs, then update it live while editing. Errors read Use at least 8 characters and Passwords must match. Invalid touched fields expose aria-invalid=true and aria-describedby to their rendered error. Register disabled until both valid. Successful submit outputs Registered. No real account is created.`,
`const [password,setPassword]=useState(''),[confirm,setConfirm]=useState(''),[touched,setTouched]=useState({}),[saved,setSaved]=useState(false);const id=useId();const pBad=password.length<8,cBad=confirm!==password||!confirm;
return <form onSubmit={e=>{e.preventDefault();if(!pBad&&!cBad)setSaved(true);}}><label>Password<input type="password" value={password} onChange={e=>setPassword(e.target.value)} onBlur={()=>setTouched(t=>({...t,password:true}))} aria-invalid={!!(touched.password&&pBad)} aria-describedby={touched.password&&pBad?id+'p':undefined}/></label>{touched.password&&pBad&&<p role="alert" id={id+'p'}>Use at least 8 characters</p>}<label>Confirm<input type="password" value={confirm} onChange={e=>setConfirm(e.target.value)} onBlur={()=>setTouched(t=>({...t,confirm:true}))} aria-invalid={!!(touched.confirm&&cBad)} aria-describedby={touched.confirm&&cBad?id+'c':undefined}/></label>{touched.confirm&&cBad&&<p role="alert" id={id+'c'}>Passwords must match</p>}<button disabled={pBad||cBad}>Register</button><output>{saved?'Registered':''}</output></form>;`,
`assert.equal(view.queryByRole('alert'),null);fireEvent.blur(field('Password'));assert.equal(view.getByRole('alert').textContent,'Use at least 8 characters');assert.equal(field('Password').getAttribute('aria-invalid'),'true');assert.equal(document.getElementById(field('Password').getAttribute('aria-describedby')).textContent,'Use at least 8 characters');change('Password','longpass');assert.equal(view.queryByRole('alert'),null);change('Confirm','wrong');fireEvent.blur(field('Confirm'));assert.equal(view.getByRole('alert').textContent,'Passwords must match');assert.equal(button('Register').disabled,true);change('Confirm','longpass');assert.equal(view.queryByRole('alert'),null);assert.equal(field('Confirm').getAttribute('aria-invalid'),'false');click('Register');assert.equal(status(),'Registered');change('Password','different');assert.equal(button('Register').disabled,true);assert.ok(view.getByText('Passwords must match'));`);

add('Normalize a phone number on submission', 'forms',
`Phone input preserves raw typing. Save strips all non-ASCII digits and accepts exactly 10 digits. Invalid submission shows role alert Enter 10 digits without clearing the raw value or the previous saved result. Valid submission clears the alert, keeps the raw input, and outputs (DDD) DDD-DDDD. Native form submission must not navigate.`,
`const [raw,setRaw]=useState(''),[saved,setSaved]=useState(''),[error,setError]=useState(false);return <form onSubmit={e=>{e.preventDefault();const digits=raw.replace(/[^0-9]/g,'');if(digits.length!==10){setError(true);return;}setError(false);setSaved('('+digits.slice(0,3)+') '+digits.slice(3,6)+'-'+digits.slice(6));}}><label>Phone<input value={raw} onChange={e=>setRaw(e.target.value)}/></label><button>Save</button>{error&&<p role="alert">Enter 10 digits</p>}<output>{saved}</output></form>;`,
`click('Save');assert.equal(view.getByRole('alert').textContent,'Enter 10 digits');change('Phone',' 212.555-0199 ');click('Save');assert.equal(status(),'(212) 555-0199');assert.equal(field('Phone').value,' 212.555-0199 ');assert.equal(view.queryByRole('alert'),null);change('Phone','123');click('Save');assert.equal(status(),'(212) 555-0199');assert.equal(field('Phone').value,'123');assert.ok(view.getByRole('alert'));change('Phone','01234567890');click('Save');assert.ok(view.getByRole('alert'));change('Phone','0123456789');click('Save');assert.equal(status(),'(012) 345-6789');`);

add('Conditional delivery fields', 'forms',
`Shipping and Pickup are radio choices in a Delivery method group, initially Shipping. Shipping displays Address and requires nonempty trimmed address; Pickup hides Address and requires no address. Switching away and back preserves its draft. Place order is disabled while invalid. Submitting outputs Ship: ADDRESS or Pickup. Changing method must not implicitly submit.`,
`const [method,setMethod]=useState('shipping'),[address,setAddress]=useState(''),[saved,setSaved]=useState('');const valid=method==='pickup'||!!address.trim();
return <form onSubmit={e=>{e.preventDefault();if(valid)setSaved(method==='pickup'?'Pickup':'Ship: '+address.trim());}}><fieldset><legend>Delivery method</legend>{['Shipping','Pickup'].map(name=><label key={name}>{name}<input type="radio" name="method" checked={method===name.toLowerCase()} onChange={()=>setMethod(name.toLowerCase())}/></label>)}</fieldset>{method==='shipping'&&<label>Address<input value={address} onChange={e=>setAddress(e.target.value)}/></label>}<button disabled={!valid}>Place order</button><output>{saved}</output></form>;`,
`assert.ok(view.getByRole('group',{name:'Delivery method'}));assert.equal(button('Place order').disabled,true);change('Address',' Main St ');fireEvent.click(view.getByRole('radio',{name:'Pickup'}));assert.equal(view.queryByLabelText('Address'),null);assert.equal(status(),'');click('Place order');assert.equal(status(),'Pickup');fireEvent.click(view.getByRole('radio',{name:'Shipping'}));assert.equal(field('Address').value,' Main St ');click('Place order');assert.equal(status(),'Ship: Main St');change('Address',' ');assert.equal(button('Place order').disabled,true);`);

add('Validate a date interval', 'forms',
`Start and End are date inputs initially empty. Reserve is enabled only when both have a date and End >= Start (same day allowed). If both provided but reversed, show role alert End must not precede start. Submission outputs START to END using ISO input values. Invalid edits must leave the last reservation unchanged. Do not use timezone conversion.`,
`const [start,setStart]=useState(''),[end,setEnd]=useState(''),[saved,setSaved]=useState('');const reversed=!!start&&!!end&&end<start,valid=!!start&&!!end&&!reversed;
return <form onSubmit={e=>{e.preventDefault();if(valid)setSaved(start+' to '+end);}}><label>Start<input type="date" value={start} onChange={e=>setStart(e.target.value)}/></label><label>End<input type="date" value={end} onChange={e=>setEnd(e.target.value)}/></label>{reversed&&<p role="alert">End must not precede start</p>}<button disabled={!valid}>Reserve</button><output>{saved}</output></form>;`,
`assert.equal(button('Reserve').disabled,true);change('Start','2026-09-20');change('End','2026-09-19');assert.equal(view.getByRole('alert').textContent,'End must not precede start');assert.equal(button('Reserve').disabled,true);change('End','2026-09-20');assert.equal(view.queryByRole('alert'),null);click('Reserve');assert.equal(status(),'2026-09-20 to 2026-09-20');change('End','2026-10-01');click('Reserve');assert.equal(status(),'2026-09-20 to 2026-10-01');change('Start','');assert.equal(button('Reserve').disabled,true);assert.equal(status(),'2026-09-20 to 2026-10-01');`);

add('Dynamic guest fields with stable identities', 'forms',
`Start with Guest 1 input and Remove guest 1 button. Add guest appends a blank input with a never-reused increasing number in its label. At least one guest must remain; disable removal of the only guest. Book disabled until every remaining guest has nonempty trimmed name. Submission outputs trimmed names joined with comma-space in current order. Removing a middle row must preserve other drafts and IDs.`,
`const next=useRef(2);const [guests,setGuests]=useState([{id:1,name:''}]),[saved,setSaved]=useState('');const valid=guests.every(g=>g.name.trim());
return <form onSubmit={e=>{e.preventDefault();if(valid)setSaved(guests.map(g=>g.name.trim()).join(', '));}}>{guests.map(g=><div key={g.id}><label>Guest {g.id}<input value={g.name} onChange={e=>{const name=e.target.value;setGuests(xs=>xs.map(x=>x.id===g.id?{...x,name}:x));}}/></label><button type="button" aria-label={'Remove guest '+g.id} disabled={guests.length===1} onClick={()=>setGuests(xs=>xs.filter(x=>x.id!==g.id))}>Remove</button></div>)}<button type="button" onClick={()=>{const id=next.current++;setGuests(xs=>[...xs,{id,name:''}]);}}>Add guest</button><button disabled={!valid}>Book</button><output>{saved}</output></form>;`,
`assert.equal(button('Remove guest 1').disabled,true);assert.equal(button('Book').disabled,true);change('Guest 1',' Ada ');click('Add guest');change('Guest 2','Bo');click('Add guest');change('Guest 3','Cy');click('Remove guest 2');assert.equal(field('Guest 3').value,'Cy');assert.equal(view.queryByLabelText('Guest 2'),null);click('Book');assert.equal(status(),'Ada, Cy');click('Add guest');assert.ok(field('Guest 4'));assert.equal(button('Book').disabled,true);click('Remove guest 4');click('Remove guest 1');assert.equal(button('Remove guest 3').disabled,true);click('Book');assert.equal(status(),'Cy');`);

add('Preview a comma-separated import', 'forms',
`Names textarea produces a live preview list. Split on commas, trim, drop empty tokens, remove case-insensitive duplicates while keeping the first spelling/order. Import disabled when preview empty or has more than 4 names. Above cap show role alert Maximum 4 names. Import commits preview joined with | to output and clears the textarea/preview. Reject over-cap submission rather than truncate.`,
`const [raw,setRaw]=useState(''),[saved,setSaved]=useState('');const seen=new Set();const names=raw.split(',').map(x=>x.trim()).filter(x=>{const key=x.toLowerCase();if(!x||seen.has(key))return false;seen.add(key);return true;});const valid=names.length>0&&names.length<=4;
return <form onSubmit={e=>{e.preventDefault();if(valid){setSaved(names.join('|'));setRaw('');}}}><label>Names<textarea value={raw} onChange={e=>setRaw(e.target.value)}/></label><ul>{names.map(x=><li key={x.toLowerCase()}>{x}</li>)}</ul>{names.length>4&&<p role="alert">Maximum 4 names</p>}<button disabled={!valid}>Import</button><output>{saved}</output></form>;`,
`assert.equal(button('Import').disabled,true);change('Names',' Ada, ,Bo,ADA, cy,bo ');assert.deepEqual(view.getAllByRole('listitem').map(x=>x.textContent),['Ada','Bo','cy']);click('Import');assert.equal(status(),'Ada|Bo|cy');assert.equal(field('Names').value,'');assert.equal(view.queryAllByRole('listitem').length,0);change('Names','a,b,c,d,e');assert.equal(button('Import').disabled,true);assert.equal(view.getByRole('alert').textContent,'Maximum 4 names');fireEvent.submit(field('Names').closest('form'));assert.equal(status(),'Ada|Bo|cy');change('Names',', ,');assert.equal(button('Import').disabled,true);`);

add('Branching feedback survey', 'forms / state',
`Step 1 has Enjoyed it checkbox (initial false) and Next. Step 2 shows Improvement textarea if unchecked, Praise textarea if checked, plus Back and Finish. Keep separate drafts for both branches when navigating. Finish requires nonempty trimmed current branch text and outputs Improvement: TEXT or Praise: TEXT, removing all controls. Variant of a wizard: changing the answer changes both the field and validation source.`,
`const [step,setStep]=useState(1),[liked,setLiked]=useState(false),[drafts,setDrafts]=useState({Praise:'',Improvement:''}),[saved,setSaved]=useState('');const branch=liked?'Praise':'Improvement';if(step===3)return <output>{saved}</output>;if(step===1)return <section><label>Enjoyed it<input type="checkbox" checked={liked} onChange={e=>setLiked(e.target.checked)}/></label><button onClick={()=>setStep(2)}>Next</button></section>;
return <section><label>{branch}<textarea value={drafts[branch]} onChange={e=>{const value=e.target.value;setDrafts(d=>({...d,[branch]:value}));}}/></label><button onClick={()=>setStep(1)}>Back</button><button disabled={!drafts[branch].trim()} onClick={()=>{setSaved(branch+': '+drafts[branch].trim());setStep(3);}}>Finish</button></section>;`,
`click('Next');assert.ok(field('Improvement'));assert.equal(button('Finish').disabled,true);change('Improvement','more time');click('Back');fireEvent.click(field('Enjoyed it'));click('Next');assert.ok(field('Praise'));assert.equal(button('Finish').disabled,true);change('Praise',' Helpful ');click('Back');fireEvent.click(field('Enjoyed it'));click('Next');assert.equal(field('Improvement').value,'more time');click('Back');fireEvent.click(field('Enjoyed it'));click('Next');assert.equal(field('Praise').value,' Helpful ');click('Finish');assert.equal(status(),'Praise: Helpful');assert.equal(view.queryAllByRole('button').length,0);`);

add('Editable inventory rows', 'CRUD',
`Props seedRows is an array of {id,name,quantity}. Editable rows: each row has Name and Qty (number) inputs labelled NAME name / NAME qty, plus Remove NAME. Add row appends {name:'',quantity:0} with a fresh unique id. Total output is total quantity. Removing keeps others intact. Snapshot button records a deep copy of current rows into an output labelled Snapshot as JSON; later edits must not alter it.`,
`let next=useRef(Math.max(0,...seedRows.map(x=>Number(x.id)))+1);const [rows,setRows]=useState(()=>seedRows.map(x=>({...x})));const [snapshot,setSnapshot]=useState('');const update=(id,patch)=>setRows(old=>old.map(x=>x.id===id?{...x,...patch}:x));
return <section>{rows.map(x=><div key={x.id}><label>{x.name||'Row'} name<input value={x.name} onChange={e=>update(x.id,{name:e.target.value})}/></label><label>{x.name||'Row'} qty<input type="number" value={x.quantity} onChange={e=>update(x.id,{quantity:Number(e.target.value)})}/></label><button aria-label={'Remove '+(x.name||'Row')} onClick={()=>setRows(old=>old.filter(y=>y.id!==x.id))}>Remove</button></div>)}<button onClick={()=>setRows(old=>[...old,{id:next.current++,name:'',quantity:0}])}>Add row</button><button onClick={()=>setSnapshot(JSON.stringify(rows))}>Snapshot</button><output aria-label="Total">{rows.reduce((s,x)=>s+x.quantity,0)}</output><output aria-label="Snapshot">{snapshot}</output></section>;`,
`assert.equal(status('Total'),'3');change('Pen qty','5');assert.equal(status('Total'),'6');change('Pen name','Pencil');assert.ok(field('Pencil qty'));assert.ok(view.queryByLabelText('Pen qty')===null);click('Snapshot');const before=JSON.parse(status('Snapshot'));change('Pencil qty','9');assert.equal(status('Total'),'10');assert.deepEqual(JSON.parse(status('Snapshot')),before);click('Remove Pencil');assert.equal(status('Total'),'1');click('Add row');assert.ok(field('Row qty'));`,
{params:'{seedRows=[]}',props:{seedRows:[{id:1,name:'Pen',quantity:2},{id:2,name:'Book',quantity:1}]}});

add('Optimistic comment list with rollback','CRUD / async',
`Props initialComments is {id,text}[], submitComment(text) resolves true/false or rejects. Comment input and Post button add a trimmed comment at the top immediately, clear the field, and disable Post while pending. Output is count. Rejected/false submissions remove only the optimistic row, restore its text to the input, show alert Post rejected, and enable retry. Success keeps the row; retry clears the alert. Existing comments must remain unchanged.`,
`const [comments,setComments]=useState(()=>initialComments.map(x=>({...x}))),[text,setText]=useState(''),[pending,setPending]=useState(false),[error,setError]=useState(false);const seq=useRef(0),live=useRef(true);useEffect(()=>{live.current=true;return()=>{live.current=false;};},[]);
async function post(){const value=text.trim();if(!value||pending)return;const id='local-'+(++seq.current);setComments(xs=>[{id,text:value},...xs]);setText('');setPending(true);setError(false);let ok=false;try{ok=await submitComment(value);}catch{}if(!live.current)return;if(!ok){setComments(xs=>xs.filter(x=>x.id!==id));setText(value);setError(true);}setPending(false);}
return <section><label>Comment<input disabled={pending} value={text} onChange={e=>setText(e.target.value)}/></label><button disabled={!text.trim()||pending} onClick={post}>Post</button>{error&&<p role="alert">Post rejected</p>}<output>{comments.length}</output><ul>{comments.map(x=><li key={x.id}>{x.text}</li>)}</ul></section>;`,
`const texts=()=>view.queryAllByRole('listitem').map(x=>x.textContent);assert.deepEqual(texts(),['first']);assert.equal(button('Post').disabled,true);change('Comment',' mine ');click('Post');assert.deepEqual(texts(),['mine','first']);assert.equal(status(),'2');assert.equal(button('Post').disabled,true);assert.equal(calls[0],'mine');await act(async()=>pending[0].resolve(true));assert.equal(field('Comment').value,'');change('Comment','bad');click('Post');assert.deepEqual(texts(),['bad','mine','first']);await act(async()=>pending[1].resolve(false));assert.deepEqual(texts(),['mine','first']);assert.equal(status(),'2');assert.equal(field('Comment').value,'bad');assert.equal(button('Post').disabled,false);assert.equal(view.getByRole('alert').textContent,'Post rejected');click('Post');assert.equal(view.queryByRole('alert'),null);await act(async()=>pending[2].reject(new Error('offline')));assert.deepEqual(texts(),['mine','first']);click('Post');await act(async()=>pending[3].resolve(true));assert.deepEqual(texts(),['bad','mine','first']);assert.deepEqual(props.initialComments,[{id:'c1',text:'first'}]);`,
{params:'{initialComments=[],submitComment}',props:{initialComments:[{id:'c1',text:'first'}]},setup:'const pending=[],calls=[];props.submitComment=text=>{calls.push(text);return new Promise((resolve,reject)=>pending.push({resolve,reject}));};Object.freeze(props.initialComments[0]);Object.freeze(props.initialComments);'});

add('Paginated people table', 'CRUD',
`Props people is {id,name,role}. 3 per page, page 1-based starting at 1, page number in a Page output. Prev/Next disabled at boundaries; a Jump to last button shows the final page. When people changes via rerender, clamp the page into the valid range instead of showing an empty page. Table with column headers Name, Role and accessible table semantics. No state duplication of props.`,
`const [page,setPage]=useState(1);const pages=Math.max(1,Math.ceil(people.length/3));const current=Math.min(page,pages);const slice=people.slice((current-1)*3,current*3);
return <section><table><thead><tr><th>Name</th><th>Role</th></tr></thead><tbody>{slice.map(x=><tr key={x.id}><td>{x.name}</td><td>{x.role}</td></tr>)}</tbody></table><button disabled={current===1} onClick={()=>setPage(current-1)}>Prev</button><output aria-label="Page">{current}</output><button disabled={current===pages} onClick={()=>setPage(current+1)}>Next</button><button onClick={()=>setPage(pages)}>Jump to last</button></section>;`,
`const page=()=>status('Page');const cells=()=>view.getAllByRole('row').slice(1).map(r=>r.cells[0].textContent);assert.equal(page(),'1');assert.deepEqual(cells(),['A','B','C']);click('Next');assert.equal(page(),'2');assert.deepEqual(cells(),['D','E','F']);click('Jump to last');assert.equal(page(),'3');assert.equal(button('Next').disabled,true);assert.deepEqual(cells(),['G']);view.rerender(React.createElement(Component,{people:props.people.slice(0,2)}));assert.equal(page(),'1');assert.deepEqual(cells(),['A','B']);assert.equal(button('Prev').disabled,true);`,
{params:'{people=[]}',props:{people:[1,2,3,4,5,6,7].map(n=>({id:n,name:String.fromCharCode(64+n),role:'r'+n}))}});

add('Expandable search over records', 'CRUD / a11y',
`Props records are {id,title,summary}. A Search input filters case-insensitively on title substring only (not summary). Render matches as buttons with aria-expanded, unexpanded rows show title only. Expanding shows the summary paragraph. Multiple rows can be expanded at once. Zero matches render an output with 0. Empty query matches all. Expansion is retained even while a row is filtered out. Row expansion must survive unrelated typing that keeps the row visible.`,
`const [query,setQuery]=useState('');const [open,setOpen]=useState(()=>new Set());const matches=records.filter(x=>x.title.toLowerCase().includes(query.toLowerCase()));
return <section><label>Search<input value={query} onChange={e=>setQuery(e.target.value)}/></label><output>{matches.length}</output><ul>{matches.map(x=><li key={x.id}><button aria-expanded={open.has(x.id)} onClick={()=>setOpen(old=>{const next=new Set(old);next.has(x.id)?next.delete(x.id):next.add(x.id);return next;})}>{x.title}</button>{open.has(x.id)&&<p>{x.summary}</p>}</li>)}</ul></section>;`,
`assert.equal(status(),'3');fireEvent.click(view.getByRole('button',{name:'Alpha report'}));assert.ok(view.getByText('A detail'));fireEvent.click(view.getByRole('button',{name:'Alphabet guide'}));assert.ok(view.getByText('B detail'));change('Search','ALP');assert.equal(status(),'2');assert.ok(view.getByText('A detail'));change('Search','zzz');assert.equal(status(),'0');assert.equal(view.queryAllByRole('listitem').length,0);change('Search','');assert.equal(view.getByRole('button',{name:'Alpha report'}).getAttribute('aria-expanded'),'true');assert.ok(view.getByText('A detail'));`,
{params:'{records=[]}',props:{records:[{id:1,title:'Alpha report',summary:'A detail'},{id:2,title:'Alphabet guide',summary:'B detail'},{id:3,title:'Zebra facts',summary:'C detail'}]}});

add('Stopwatch with start and stop', 'effects',
`Use a real interval: running output says running/stopped. Start begins a seconds counter from 0 in an output labelled Seconds, ticking every second. Stop freezes it; Start again resumes from the current value (no reset). Reset returns to 0 while stopped. Start must be disabled while running. Use setInterval inside useEffect with a cleanup that clears it. Test uses fake timers.`,
`const [seconds,setSeconds]=useState(0),[running,setRunning]=useState(false);useEffect(()=>{if(!running)return;const id=setInterval(()=>setSeconds(s=>s+1),1000);return()=>clearInterval(id);},[running]);
return <section><output aria-label="Seconds">{seconds}</output><output aria-label="State">{running?'running':'stopped'}</output><button disabled={running} onClick={()=>setRunning(true)}>Start</button><button disabled={!running} onClick={()=>setRunning(false)}>Stop</button><button onClick={()=>{setRunning(false);setSeconds(0);}}>Reset</button></section>;`,
`clock.useFakeTimers();const sec=()=>status('Seconds');assert.equal(sec(),'0');assert.equal(button('Start').disabled,false);click('Start');assert.equal(button('Start').disabled,true);assert.equal(status('State'),'running');act(()=>{clock.advanceTimersByTime(3000);});assert.equal(sec(),'3');click('Stop');act(()=>{clock.advanceTimersByTime(5000);});assert.equal(sec(),'3');click('Start');act(()=>{clock.advanceTimersByTime(1000);});assert.equal(sec(),'4');click('Reset');assert.equal(sec(),'0');assert.equal(status('State'),'stopped');assert.equal(clock.getTimerCount(),0);click('Start');assert.equal(clock.getTimerCount(),1);view.unmount();assert.equal(clock.getTimerCount(),0);`,
{setup:'clock.useFakeTimers();'});

add('Interval ticker / changing-step debugging variant', 'effects / debugging',
`An interval every 100ms increments count by props.step, captured fresh on each tick (fix the stale-closure bug by using functional updates or including step in deps). Mount starts paused; Start/Stop toggle running; outputs labelled Count and Step show count and current step. Unmount must stop the interval: assert by unmounting and advancing timers without errors and no further updates. Test uses fake timers.`,
`const [count,setCount]=useState(0),[running,setRunning]=useState(false);useEffect(()=>{if(!running)return;const id=setInterval(()=>setCount(c=>c+step),100);return()=>clearInterval(id);},[running,step]);
return <section><output aria-label="Count">{count}</output><output aria-label="Step">{step}</output><button onClick={()=>setRunning(r=>!r)}>{running?'Stop':'Start'}</button></section>;`,
`clock.useFakeTimers();const count=()=>status('Count');assert.equal(count(),'0');click('Start');act(()=>{clock.advanceTimersByTime(500);});assert.equal(count(),'5');click('Stop');act(()=>{clock.advanceTimersByTime(400);});assert.equal(count(),'5');click('Start');act(()=>{clock.advanceTimersByTime(200);});assert.equal(count(),'7');view.rerender(React.createElement(Component,{step:5}));act(()=>{clock.advanceTimersByTime(100);});assert.equal(count(),'12');view.unmount();assert.equal(clock.getTimerCount(),0);act(()=>{clock.advanceTimersByTime(1000);});assert.equal(document.body.textContent,'');`,
{params:'{step=1}',props:{step:1}});

add('Debounced search indicator', 'effects',
`Query input updates output immediately with echo. While waiting, output is the query followed by an ellipsis (…). After 300ms without edits, remove the ellipsis. Initial empty query is settled. Clearing a nonempty query also waits 300ms. Use setTimeout inside useEffect keyed on the query with proper cleanup. Test uses fake timers to advance time.`,
`const [text,setText]=useState(''),[settled,setSettled]=useState(true);const mounted=useRef(false);useEffect(()=>{if(!mounted.current){mounted.current=true;return;}setSettled(false);const id=setTimeout(()=>setSettled(true),300);return()=>clearTimeout(id);},[text]);
return <section><label>Query<input value={text} onChange={e=>setText(e.target.value)}/></label><output>{text}{settled?'':'…'}</output></section>;`,
`clock.useFakeTimers();change('Query','ab');assert.equal(status(),'ab…');act(()=>{clock.advanceTimersByTime(150);});change('Query','abc');assert.equal(status(),'abc…');act(()=>{clock.advanceTimersByTime(200);});assert.equal(status(),'abc…');act(()=>{clock.advanceTimersByTime(200);});assert.equal(status(),'abc');act(()=>{clock.advanceTimersByTime(1000);});assert.equal(status(),'abc');change('Query','');assert.equal(status(),'…');act(()=>{clock.advanceTimersByTime(300);});assert.equal(status(),'');`,
{});

add('Ignore stale profile responses','async',
`Props fetchUser(id) returns Promise<{id,name}>. userId defaults to 1. On mount and each changed userId, output User shows loading, then the latest user's name; errors show output error and role alert message. Ignore stale success and failure after a newer request or unmount. Use an effect cleanup flag; do not make network calls outside the injected service.`,
`const [state,setState]=useState({status:'loading',name:'',error:''});useEffect(()=>{let live=true;setState({status:'loading',name:'',error:''});Promise.resolve().then(()=>fetchUser(userId)).then(user=>{if(live)setState({status:'ready',name:user.name,error:''});},e=>{if(live)setState({status:'error',name:'',error:e.message});});return()=>{live=false;};},[userId,fetchUser]);return <section><output aria-label="User">{state.status==='ready'?state.name:state.status}</output>{state.status==='error'&&<p role="alert">{state.error}</p>}</section>;`,
`assert.equal(status('User'),'loading');await act(async()=>{});view.rerender(React.createElement(Component,{fetchUser:props.fetchUser,userId:2}));await act(async()=>{});await act(async()=>requests[2].resolve({id:2,name:'Ben'}));assert.equal(status('User'),'Ben');await act(async()=>requests[1].resolve({id:1,name:'Ann'}));assert.equal(status('User'),'Ben');view.rerender(React.createElement(Component,{fetchUser:props.fetchUser,userId:3}));await act(async()=>{});assert.equal(status('User'),'loading');view.rerender(React.createElement(Component,{fetchUser:props.fetchUser,userId:4}));await act(async()=>{});await act(async()=>requests[3].reject(new Error('stale')));assert.equal(view.queryByRole('alert'),null);await act(async()=>requests[4].reject(new Error('offline')));assert.equal(status('User'),'error');assert.equal(view.getByRole('alert').textContent,'offline');view.rerender(React.createElement(Component,{fetchUser:props.fetchUser,userId:5}));await act(async()=>{});assert.equal(view.queryByRole('alert'),null);view.unmount();await act(async()=>requests[5].resolve({id:5,name:'late'}));assert.equal(document.body.textContent,'');`,
{params:'{userId=1,fetchUser}',setup:'const requests={};props.fetchUser=id=>new Promise((resolve,reject)=>{requests[id]={resolve,reject};});'});

add('Restart an in-flight job','async',
`Props runTask(job) returns Promise<string>; job defaults to 1. Start is always enabled and launches a new request, superseding any previous request. Output idle/loading/DONE:RESULT/error; rejection of the current request also shows an alert message. Older success or failure must never change output. Ignore completion after unmount.`,
`const [state,setState]=useState({status:'idle',value:''});const current=useRef(0);useEffect(()=>()=>{current.current++;},[]);async function go(){const ticket=++current.current;setState({status:'loading',value:''});try{const value=await runTask(job);if(ticket===current.current)setState({status:'done',value});}catch(e){if(ticket===current.current)setState({status:'error',value:e.message});}}return <section><button onClick={go}>Start</button><output>{state.status==='done'?'DONE:'+state.value:state.status}</output>{state.status==='error'&&<p role="alert">{state.value}</p>}</section>;`,
`assert.equal(status(),'idle');click('Start');assert.equal(status(),'loading');assert.equal(button('Start').disabled,false);view.rerender(React.createElement(Component,{runTask:props.runTask,job:2}));click('Start');assert.deepEqual(calls,[1,2]);await act(async()=>pending[1].resolve('fast'));assert.equal(status(),'DONE:fast');await act(async()=>pending[0].resolve('slow'));assert.equal(status(),'DONE:fast');click('Start');click('Start');await act(async()=>pending[2].reject(new Error('stale')));assert.equal(view.queryByRole('alert'),null);assert.equal(status(),'loading');await act(async()=>pending[3].reject(new Error('offline')));assert.equal(status(),'error');assert.equal(view.getByRole('alert').textContent,'offline');click('Start');assert.equal(view.queryByRole('alert'),null);await act(async()=>pending[4].resolve('retry'));assert.equal(status(),'DONE:retry');`,
{params:'{job=1,runTask}',setup:'const calls=[],pending=[];props.runTask=job=>{calls.push(job);return new Promise((resolve,reject)=>pending.push({resolve,reject}));};'});

add('Batch fetch with partial failure','async',
`Props fetchOne(id) returns Promise<string>; ids defaults to [1,2,3]. Load concurrently fetches each id. Output initially idle, loading while pending, then results joined with | in input-id order; failed slots are (failed). Alert lists only failed ids joined with commas in input order. Disable Load while pending. A new load clears the previous alert. Empty ids results in an empty output. Use Promise.allSettled.`,
`const [state,setState]=useState({status:'idle',text:'',failed:[]});const live=useRef(true);useEffect(()=>{live.current=true;return()=>{live.current=false;};},[]);async function run(){setState({status:'loading',text:'',failed:[]});const results=await Promise.allSettled(ids.map(id=>Promise.resolve().then(()=>fetchOne(id))));if(!live.current)return;const failed=[];const text=results.map((r,i)=>{if(r.status==='fulfilled')return r.value;failed.push(ids[i]);return '(failed)';}).join('|');setState({status:'done',text,failed});}return <section><button disabled={state.status==='loading'} onClick={run}>Load</button><output>{state.status==='done'?state.text:state.status}</output>{state.failed.length>0&&<p role="alert">{state.failed.join(',')}</p>}</section>;`,
`assert.equal(status(),'idle');click('Load');assert.equal(status(),'loading');assert.equal(button('Load').disabled,true);await act(async()=>{});assert.deepEqual(calls,[1,2,3]);await act(async()=>pending[3].resolve('v3'));await act(async()=>pending[1].resolve('v1'));assert.equal(status(),'loading');await act(async()=>pending[2].reject(new Error('bad')));assert.equal(status(),'v1|(failed)|v3');assert.equal(view.getByRole('alert').textContent,'2');assert.equal(button('Load').disabled,false);view.rerender(React.createElement(Component,{fetchOne:async id=>'v'+id,ids:[3,1]}));await act(async()=>click('Load'));assert.equal(status(),'v3|v1');assert.equal(view.queryByRole('alert'),null);view.rerender(React.createElement(Component,{fetchOne:props.fetchOne,ids:[]}));await act(async()=>click('Load'));assert.equal(status(),'');`,
{params:'{ids=[1,2,3],fetchOne}',setup:'const pending={},calls=[];props.fetchOne=id=>{calls.push(id);return new Promise((resolve,reject)=>pending[id]={resolve,reject});};'});

add('Poll for status until ready','async / effects',
`Props check() resolves pending/ready. Start begins polling every 200ms; initial output idle, active output Polling…, ready output Ready. Start disabled once started. Avoid overlapping checks if a response takes over 200ms. On rejection stop polling and show output error plus alert message. Cleanup the interval on unmount and ignore outstanding results.`,
`const [state,setState]=useState('idle'),[error,setError]=useState('');const timer=useRef(null),busy=useRef(false),live=useRef(true);useEffect(()=>{live.current=true;return()=>{live.current=false;clearInterval(timer.current);};},[]);function start(){setState('Polling…');timer.current=setInterval(async()=>{if(busy.current)return;busy.current=true;try{const value=await check();if(live.current&&value==='ready'){clearInterval(timer.current);timer.current=null;setState('Ready');}}catch(e){if(live.current){clearInterval(timer.current);timer.current=null;setError(e.message);setState('error');}}finally{busy.current=false;}},200);}return <section><button disabled={state!=='idle'} onClick={start}>Start</button><output>{state}</output>{error&&<p role="alert">{error}</p>}</section>;`,
`clock.useFakeTimers();assert.equal(status(),'idle');click('Start');assert.equal(status(),'Polling…');assert.equal(button('Start').disabled,true);await act(async()=>clock.advanceTimersByTime(200));assert.equal(calls,1);await act(async()=>clock.advanceTimersByTime(600));assert.equal(calls,1);await act(async()=>pending[0].resolve('pending'));await act(async()=>clock.advanceTimersByTime(200));assert.equal(calls,2);await act(async()=>pending[1].resolve('ready'));assert.equal(status(),'Ready');assert.equal(clock.getTimerCount(),0);view.unmount();const second=render(React.createElement(Component,{check:props.check}));fireEvent.click(within(second.container).getByRole('button',{name:'Start'}));await act(async()=>clock.advanceTimersByTime(200));await act(async()=>pending[2].reject(new Error('offline')));assert.equal(within(second.container).getByRole('alert').textContent,'offline');assert.equal(clock.getTimerCount(),0);second.unmount();const third=render(React.createElement(Component,{check:props.check}));fireEvent.click(within(third.container).getByRole('button',{name:'Start'}));await act(async()=>clock.advanceTimersByTime(200));third.unmount();assert.equal(clock.getTimerCount(),0);await act(async()=>pending[3].resolve('ready'));assert.equal(document.body.textContent,'');`,
{params:'{check}',setup:'const pending=[];let calls=0;props.check=()=>{calls++;return new Promise((resolve,reject)=>pending.push({resolve,reject}));};'});

add('Debounced save with flushed unsaved state', 'effects',
`Text input auto-saves 400ms after the last keystroke. Unsaved output says Unsaved changes or Saved; a Save now button flushes immediately (disabled when nothing pending). Navigating away (unmount) must not throw. After save, output returns to Saved. Use effect + timeout with the right dependency list so repeated typing does not save each keystroke.`,
`const [text,setText]=useState(''),[saved,setSaved]=useState(''),[dirty,setDirty]=useState(false);const timer=useRef(null);useEffect(()=>{if(!dirty)return;timer.current=setTimeout(()=>{setSaved(text);setDirty(false);},400);return()=>clearTimeout(timer.current);},[dirty,text]);
return <section><label>Text<input value={text} onChange={e=>{setText(e.target.value);setDirty(true);}}/></label><button disabled={!dirty} onClick={()=>{clearTimeout(timer.current);setSaved(text);setDirty(false);}}>Save now</button><output>{dirty?'Unsaved changes':saved?'Saved':'Saved'}</output><output aria-label="Value">{saved}</output></section>;`,
`clock.useFakeTimers();const value=()=>status('Value');assert.equal(status(),'Saved');change('Text','a');assert.equal(status(),'Unsaved changes');act(()=>{clock.advanceTimersByTime(200);});change('Text','ab');act(()=>{clock.advanceTimersByTime(300);});assert.equal(value(),'');assert.equal(status(),'Unsaved changes');act(()=>{clock.advanceTimersByTime(450);});assert.equal(value(),'ab');assert.equal(status(),'Saved');change('Text','abc');click('Save now');assert.equal(value(),'abc');assert.equal(status(),'Saved');assert.equal(button('Save now').disabled,true);act(()=>clock.advanceTimersByTime(1000));assert.equal(value(),'abc');change('Text','later');assert.equal(clock.getTimerCount(),1);view.unmount();assert.equal(clock.getTimerCount(),0);`,
{});

add('Typewriter effect with cleanup', 'effects',
`When playing, reveal one character of the fixed message every 150ms into a Visible output; when finished (or paused), stop advancing. Play/Pause toggles playing; Play resumes mid-word. At completion, keep the Play button disabled. Reset clears the visible text and pauses. Output Label shows playing/paused/done. Must clean up its timer on unmount and on pause. Test uses fake timers.`,
`const [chars,setChars]=useState(0),[playing,setPlaying]=useState(false);const done=chars>=text.length;useEffect(()=>{if(!playing||done)return;const id=setInterval(()=>setChars(c=>Math.min(text.length,c+1)),150);return()=>clearInterval(id);},[playing,done,text]);
return <section><output aria-label="Visible">{text.slice(0,chars)}</output><output aria-label="Label">{done?'done':playing?'playing':'paused'}</output><button disabled={done} onClick={()=>setPlaying(p=>!p)}>{playing&&!done?'Pause':'Play'}</button><button onClick={()=>{setPlaying(false);setChars(0);}}>Reset</button></section>;`,
`clock.useFakeTimers();const vis=()=>status('Visible');assert.equal(vis(),'');click('Play');act(()=>{clock.advanceTimersByTime(450);});assert.equal(vis(),'abc');click('Pause');act(()=>{clock.advanceTimersByTime(500);});assert.equal(vis(),'abc');click('Play');act(()=>{clock.advanceTimersByTime(450);});assert.equal(vis(),'abcdef');assert.equal(status('Label'),'done');assert.equal(button('Play').disabled,true);assert.equal(clock.getTimerCount(),0);click('Reset');assert.equal(vis(),'');assert.equal(status('Label'),'paused');click('Play');act(()=>clock.advanceTimersByTime(150));assert.equal(vis(),'a');view.unmount();assert.equal(clock.getTimerCount(),0);`,
{params:'{text="abcdef"}'});

add('Track window focus changes', 'effects',
`Output focused/blur must track the real window focus and blur events (jsdom fires them). Register listeners on window in one effect and remove them on unmount; no stale listeners after unmount (unmount then fire blur and confirm nothing crashes). Initial value focused. A Blur now button dispatches a real window blur event for the test.`,
`const [focused,setFocused]=useState(true);useEffect(()=>{const on=()=>setFocused(true),off=()=>setFocused(false);window.addEventListener('focus',on);window.addEventListener('blur',off);return()=>{window.removeEventListener('focus',on);window.removeEventListener('blur',off);};},[]);
return <section><output>{focused?'focused':'blur'}</output><button onClick={()=>{window.dispatchEvent(new window.Event('blur'));}}>Blur now</button><button onClick={()=>{window.dispatchEvent(new window.Event('focus'));}}>Focus now</button></section>;`,
`assert.equal(status(),'focused');click('Blur now');assert.equal(status(),'blur');click('Focus now');assert.equal(status(),'focused');fireEvent.blur(window);assert.equal(status(),'blur');view.unmount();fireEvent.focus(window);assert.equal(document.body.textContent,'');for(const [type,listener] of added)assert.ok(removed.some(([t,l])=>t===type&&l===listener),'listener removed: '+type);`,{setup:"const added=[],removed=[];const oldAdd=window.addEventListener,oldRemove=window.removeEventListener;window.addEventListener=function(type,fn,...rest){if(type==='focus'||type==='blur')added.push([type,fn]);return oldAdd.call(this,type,fn,...rest);};window.removeEventListener=function(type,fn,...rest){if(type==='focus'||type==='blur')removed.push([type,fn]);return oldRemove.call(this,type,fn,...rest);};"});

add('Focus trap within a dialog', 'a11y',
`Open via Open button. Dialog (role dialog, aria-label Wizard) contains two buttons First and Last. Tab from Last wraps to First; Shift+Tab from First wraps to Last. Focus the First button automatically when the dialog opens. Close button unmounts it. Implement with keydown handling on the dialog container. Output states open/closed.`,
`const [open,setOpen]=useState(false);const ref=useRef(null);const onKey=e=>{if(e.key!=='Tab')return;const buttons=ref.current?Array.from(ref.current.querySelectorAll('button')).filter(x=>!x.disabled):[];if(!buttons.length)return;const first=buttons[0],last=buttons[buttons.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}};
return <section><button onClick={()=>{setOpen(true);}}>Open</button><output>{open?'open':'closed'}</output>{open&&<div role="dialog" aria-label="Wizard" ref={el=>{ref.current=el;}} onKeyDown={onKey}><button autoFocus>First</button><button onClick={()=>setOpen(false)}>Close</button><button>Last</button></div>}</section>;`,
`assert.equal(status(),'closed');click('Open');const dialog=view.getByRole('dialog',{name:'Wizard'});assert.equal(document.activeElement,within(dialog).getByText('First'));within(dialog).getByText('Last').focus();fireEvent.keyDown(within(dialog).getByText('Last'),{key:'Tab'});assert.equal(document.activeElement,within(dialog).getByText('First'));fireEvent.keyDown(within(dialog).getByText('First'),{key:'Tab',shiftKey:true});assert.equal(document.activeElement,within(dialog).getByText('Last'));click('Close');assert.equal(status(),'closed');`);

add('Form with labelled error summary', 'a11y / forms',
`Contact form: Name (>=2 chars), Email (contains @), Message (nonempty trimmed). On submit with any invalid field, render a role alert summary listing each problem sentence in order: Enter a name, Enter a valid email, Enter a message, plus focus the first invalid input. Valid submission shows output Sent: NAME and clears errors. Errors are recalculated on each submit attempt. Successful submission clears all fields.`,
`const [fields,setFields]=useState({name:'',email:'',message:''}),[errors,setErrors]=useState([]),[sent,setSent]=useState('');const nameRef=useRef(null),emailRef=useRef(null),messageRef=useRef(null);const set=key=>e=>{const value=e.target.value;setFields(f=>({...f,[key]:value}));};
return <form onSubmit={e=>{e.preventDefault();const list=[];if(fields.name.trim().length<2)list.push('Enter a name');if(!fields.email.includes('@'))list.push('Enter a valid email');if(!fields.message.trim())list.push('Enter a message');setErrors(list);if(list.length){const target={ 'Enter a name':nameRef,'Enter a valid email':emailRef,'Enter a message':messageRef }[list[0]];if(target&&target.current)target.current.focus();return;}setSent(fields.name.trim());setFields({name:'',email:'',message:''});}}>
<label>Name<input ref={nameRef} value={fields.name} onChange={set('name')}/></label><label>Email<input ref={emailRef} value={fields.email} onChange={set('email')}/></label><label>Message<textarea ref={messageRef} value={fields.message} onChange={set('message')}/></label><button>Submit</button>{errors.length>0&&<p role="alert">{errors.join(' ')}</p>}<output>{sent?'Sent: '+sent:''}</output></form>;`,
`click('Submit');assert.equal(view.getByRole('alert').textContent,'Enter a name Enter a valid email Enter a message');assert.equal(document.activeElement,field('Name'));change('Name','Ada');change('Email','nope');change('Message','hi');click('Submit');assert.equal(view.getByRole('alert').textContent,'Enter a valid email');assert.equal(document.activeElement,field('Email'));change('Email','a@b.c');click('Submit');assert.equal(status(),'Sent: Ada');assert.equal(view.queryByRole('alert'),null);assert.equal(field('Name').value,'');`);

add('Described-by hint and error pairing', 'a11y',
`Username input with a permanent hint paragraph labelled by an id (text: Lowercase letters and digits only) always rendered and wired via aria-describedby. Validation: only lowercase letters/digits, 3..10 chars. Error paragraph (role alert, same id as hint is NOT allowed — use a second id) with text Use 3-10 lowercase letters or digits appears only when invalid and input has been touched (blur). Set aria-invalid on the input while the error shows.`,
`const id=useId();const [value,setValue]=useState(''),[touched,setTouched]=useState(false);const invalid=touched&&!/^[a-z0-9]{3,10}$/.test(value);
return <section><label>Username<input value={value} onChange={e=>setValue(e.target.value)} onBlur={()=>setTouched(true)} aria-describedby={id+'hint'+(invalid?' '+id+'err':'')} aria-invalid={invalid}/></label><p id={id+'hint'}>Lowercase letters and digits only</p>{invalid&&<p role="alert" id={id+'err'}>Use 3-10 lowercase letters or digits</p>}<output>{invalid?'invalid':'valid'}</output></section>;`,
`const input=field('Username');assert.ok(input.getAttribute('aria-describedby'));fireEvent.blur(input);assert.equal(view.getByRole('alert').textContent,'Use 3-10 lowercase letters or digits');assert.equal(input.getAttribute('aria-invalid'),'true');const ids=input.getAttribute('aria-describedby').split(' ');assert.ok(ids.length===2);assert.notEqual(ids[0],ids[1]);assert.equal(document.getElementById(ids[0]).textContent,'Lowercase letters and digits only');assert.equal(document.getElementById(ids[1]).textContent,'Use 3-10 lowercase letters or digits');change('Username','okay');assert.equal(status(),'valid');change('Username','AB');fireEvent.blur(input);assert.equal(view.getByRole('alert').textContent,'Use 3-10 lowercase letters or digits');change('Username','goodname');assert.equal(view.queryByRole('alert'),null);assert.equal(input.getAttribute('aria-invalid'),'false');assert.equal(input.getAttribute('aria-describedby').split(' ').length,1);`);

add('Roving tabindex list navigation', 'a11y',
`A vertical list of 4 fruits (aria-label Fruits) rendered as buttons in listitems. Exactly one is focusable via roving tabindex matching selection. ArrowDown/ArrowUp move selection and focus (no wrap needed beyond ends: clamp). Home/End select first/last. Click selects and focuses. Output shows the selected fruit. Variant of tab-pattern: same roving concept, list semantics.`,
`const fruits=['Apple','Banana','Cherry','Date'];const [index,setIndex]=useState(0);const refs=useRef([]);const move=next=>{const clamped=Math.max(0,Math.min(fruits.length-1,next));setIndex(clamped);refs.current[clamped].focus();};
return <section><ul aria-label="Fruits">{fruits.map((name,i)=><li key={name}><button ref={el=>{refs.current[i]=el;}} tabIndex={index===i?0:-1} onClick={()=>move(i)} onKeyDown={e=>{const targets={ArrowDown:i+1,ArrowUp:i-1,Home:0,End:fruits.length-1};if(Object.hasOwn(targets,e.key)){e.preventDefault();move(targets[e.key]);}}}>{name}</button></li>)}</ul><output>{fruits[index]}</output></section>;`,
`const items=()=>within(view.getByRole('list',{name:'Fruits'})).getAllByRole('button');const focusables=()=>items().filter(x=>x.tabIndex===0).map(x=>x.textContent);assert.deepEqual(focusables(),['Apple']);fireEvent.keyDown(items()[0],{key:'ArrowDown'});assert.equal(status(),'Banana');assert.deepEqual(focusables(),['Banana']);assert.equal(document.activeElement,items()[1]);fireEvent.keyDown(items()[1],{key:'ArrowUp'});fireEvent.keyDown(items()[0],{key:'ArrowUp'});assert.equal(status(),'Apple');fireEvent.keyDown(items()[0],{key:'End'});assert.equal(status(),'Date');fireEvent.keyDown(items()[3],{key:'Home'});assert.equal(status(),'Apple');fireEvent.click(items()[2]);assert.equal(status(),'Cherry');assert.deepEqual(focusables(),['Cherry']);assert.equal(document.activeElement,items()[2]);`);

add('Accessible star rating', 'a11y',
`5 buttons labelled Rate X out of 5 (X=1..5). aria-pressed reflects rating; unrated initially (output 0). Each button text is the star character repeated X times plus ' Rate X out of 5' aria-label semantics via accessible name. Click sets the rating; output shows the number. Clear button resets to 0. Radiogroup alternative is not required; buttons suffice. Buttons must be individually addressable by role button and name Rate X out of 5.`,
`const [rating,setRating]=useState(0);return <section role="group" aria-label="Rating">{[1,2,3,4,5].map(x=><button key={x} aria-pressed={rating===x} aria-label={'Rate '+x+' out of 5'} onClick={()=>setRating(x)}>{'★'.repeat(x)}</button>)}<output>{rating}</output><button onClick={()=>setRating(0)}>Clear</button></section>;`,
`assert.equal(status(),'0');fireEvent.click(view.getByRole('button',{name:'Rate 3 out of 5'}));assert.equal(status(),'3');assert.equal(view.getByRole('button',{name:'Rate 3 out of 5'}).getAttribute('aria-pressed'),'true');assert.equal(view.getByRole('button',{name:'Rate 5 out of 5'}).getAttribute('aria-pressed'),'false');fireEvent.click(view.getByRole('button',{name:'Rate 5 out of 5'}));assert.equal(status(),'5');click('Clear');assert.equal(status(),'0');`);

add('Skip link and landmark order', 'a11y',
`Render: a skip link (a element) with text Skip to content pointing to #main, a banner landmark (header with aria-label Site header) containing a nav with two links Home, About, then main landmark with aria-label Main content holding a paragraph. Skip link href must be exactly #main and the main landmark must have id main. Include at least one other element between them to make the skip meaningful. Verify DOM order: skip link first child of the outer section.`,
`return <section><a href="#main">Skip to content</a><header aria-label="Site header"><nav><a href="#home">Home</a><a href="#about">About</a></nav></header><div aria-hidden="true">decorative strip</div><main id="main" aria-label="Main content" tabIndex={-1}><h1>Welcome</h1><p>Body copy.</p></main></section>;`,
`const section=view.container.firstElementChild;assert.equal(section.firstElementChild.textContent,'Skip to content');assert.equal(section.firstElementChild.getAttribute('href'),'#main');assert.ok(view.getByRole('banner',{name:'Site header'}));assert.ok(view.getByRole('navigation'));assert.ok(view.getByRole('main',{name:'Main content'}));assert.equal(view.getByRole('main').id,'main');assert.ok(view.getByRole('link',{name:'Home'}));assert.ok(view.getByRole('link',{name:'About'}));`);

add('Tree of expandable folders', 'a11y / state',
`Props tree nodes: {id,name,children?}. Render folders as buttons with aria-expanded inside nested uls; files as plain listitem text. Click toggles that folder only. Initially all collapsed. Expanding a parent reveals its children in the DOM. Data has 2 levels. Use recursion or a flat map; do not mutate props.`,
`const [open,setOpen]=useState(()=>new Set());const render=node=>{const hasChildren=Array.isArray(node.children);return <li key={node.id}>{hasChildren?<button aria-expanded={open.has(node.id)} onClick={()=>setOpen(old=>{const next=new Set(old);next.has(node.id)?next.delete(node.id):next.add(node.id);return next;})}>{node.name}</button>:node.name}{hasChildren&&open.has(node.id)&&<ul>{node.children.map(render)}</ul>}</li>;};
return <section><ul>{tree.map(render)}</ul></section>;`,
`const lists=view.getAllByRole('list');assert.equal(view.queryByText('index.js'),null);click('src');assert.ok(view.getByText('src'));assert.equal(view.getByRole('button',{name:'src'}).getAttribute('aria-expanded'),'true');assert.ok(view.getByText('index.js'));assert.ok(view.getByText('components'));click('components');assert.ok(view.getByText('Button.jsx'));click('src');assert.equal(view.queryByText('components'),null);assert.ok(view.getByText('readme.md'));`,
{params:'{tree=[]}',props:{tree:[{id:1,name:'src',children:[{id:2,name:'index.js'},{id:3,name:'components',children:[{id:4,name:'Button.jsx'}]}]},{id:5,name:'readme.md'}]}});

add('Keyed list with prepend and remove', 'state / lists',
`Props initialNames is an ordered array of unique strings. A name input plus Add to top button prepends a trimmed nonempty unique name (case-insensitive uniqueness; reject silently if duplicate/empty). Each row has Remove X. Row numbers 1..N render before each name inside the listitem. New names must appear at index 0 with correct renumbering. Output count. Never reuse key-based DOM identity incorrectly: keys must be the name string.`,
`const [names,setNames]=useState(()=>[...initialNames]);const [text,setText]=useState('');
const add=()=>{const value=text.trim();if(!value)return;if(names.some(x=>x.toLowerCase()===value.toLowerCase()))return;setNames(old=>[value,...old]);setText('');};
return <section><label>New name<input value={text} onChange={e=>setText(e.target.value)}/></label><button onClick={add}>Add to top</button><ol>{names.map((name,i)=><li key={name}><span>{i+1}</span> {name}<button aria-label={'Remove '+name} onClick={()=>setNames(old=>old.filter(x=>x!==name))}>x</button></li>)}</ol><output>{names.length}</output></section>;`,
`const items=()=>view.getAllByRole('listitem').map(x=>x.textContent);assert.equal(status(),'3');change('New name',' Zed ');click('Add to top');assert.deepEqual(items(),['1 Zedx','2 Adax','3 Box','4 Cyx']);assert.equal(field('New name').value,'');change('New name','  ');click('Add to top');assert.equal(status(),'4');change('New name','zed');click('Add to top');assert.equal(status(),'4');assert.equal(field('New name').value,'zed');click('Remove Ada');assert.equal(status(),'3');assert.deepEqual(items(),['1 Zedx','2 Box','3 Cyx']);assert.deepEqual(props.initialNames,['Ada','Bo','Cy']);`,
{params:'{initialNames=[]}',props:{initialNames:['Ada','Bo','Cy']}});

add('Combine category and minimum-rating filters', 'state',
`Props entries: {id,title,kind,stars}. A Kind select (all/kindA/kindB, initial all) filters by exact kind; a Stars select (all/2/3, initial all) keeps entries with stars >= value. Both filters combine. Output is matched count. List shows title only. Never mutate props; ordering stays as provided.`,
`const [kind,setKind]=useState('all'),[minStars,setMinStars]=useState('all');const filtered=entries.filter(x=>(kind==='all'||x.kind===kind)&&(minStars==='all'||x.stars>=Number(minStars)));
return <section><label>Kind<select value={kind} onChange={e=>setKind(e.target.value)}>{['all','kindA','kindB'].map(x=><option key={x}>{x}</option>)}</select></label><label>Stars<select value={minStars} onChange={e=>setMinStars(e.target.value)}>{['all','2','3'].map(x=><option key={x}>{x}</option>)}</select></label><ul>{filtered.map(x=><li key={x.id}>{x.title}</li>)}</ul><output>{filtered.length}</output></section>;`,
`const titles=()=>view.queryAllByRole('listitem').map(x=>x.textContent);assert.equal(status(),'4');change('Kind','kindA');assert.equal(status(),'2');change('Stars','3');assert.equal(status(),'1');assert.deepEqual(titles(),['Alpha one']);change('Kind','kindB');assert.equal(status(),'1');assert.deepEqual(titles(),['Delta four']);change('Kind','all');assert.equal(status(),'2');change('Stars','all');change('Kind','kindA');change('Stars','3');assert.deepEqual(titles(),['Alpha one']);`,
{params:'{entries=[]}',props:{entries:[{id:1,title:'Alpha one',kind:'kindA',stars:3},{id:2,title:'Beta two',kind:'kindB',stars:2},{id:3,title:'Gamma three',kind:'kindA',stars:2},{id:4,title:'Delta four',kind:'kindB',stars:3}]}});

add('Copy to clipboard button', 'effects',
`Props text (default props-text). Button Copy labelled Copy uses a navigator.clipboard stub (defined in the test via Object.assign(navigator,{clipboard:{writeText:clock.fn(()=>Promise.resolve())}})). Initial output idle; after success output copied; on failure output failed. Failure path (stub rejects) shows role alert Copy failed. Button must call writeText exactly once with props.text. Restore clipboard after test.`,
`const [state,setState]=useState('idle');const write=()=>{navigator.clipboard.writeText(text).then(()=>setState('copied')).catch(()=>setState('failed'));};
return <section><button onClick={write}>Copy</button><output>{state}</output>{state==='failed'&&<p role="alert">Copy failed</p>}</section>;`,
`const writeText=clock.fn(()=>Promise.resolve());Object.defineProperty(navigator,'clipboard',{value:{writeText},configurable:true});click('Copy');await act(async()=>{});assert.equal(writeText.mock.calls.length,1);assert.equal(writeText.mock.calls[0][0],'props-text');assert.equal(status(),'copied');Object.defineProperty(navigator,'clipboard',{value:{writeText:clock.fn(()=>Promise.reject(new Error('denied')))},configurable:true});click('Copy');await act(async()=>{});assert.equal(view.getByRole('alert').textContent,'Copy failed');assert.equal(status(),'failed');`,
{params:'{text="props-text"}',cleanup:'try{delete navigator.clipboard}catch(e){}'});

add('Persist a draft to sessionStorage', 'effects',
`Text input whose value seeds from sessionStorage key draft-junior (read once on mount; missing means empty string). Each change writes the raw value back to sessionStorage. Clear draft empties input and removes the key. Unmount and re-mount must restore the last draft. Guard every storage access with try/catch so private-mode failures do not crash. Output echoes current input.`,
`const KEY='draft-junior';const [text,setText]=useState(()=>{try{return window.sessionStorage.getItem(KEY)||'';}catch(e){return '';}});useEffect(()=>{try{if(text==='')window.sessionStorage.removeItem(KEY);else window.sessionStorage.setItem(KEY,text);}catch(e){}},[text]);
return <section><label>Text<input value={text} onChange={e=>setText(e.target.value)}/></label><button onClick={()=>{setText('');try{window.sessionStorage.removeItem(KEY);}catch(e){}}}>Clear draft</button><output>{text}</output></section>;`,
`assert.equal(field('Text').value,'preset');change('Text','persisted');view.unmount();const second=render(React.createElement(Component,{}));assert.equal(second.getByLabelText('Text').value,'persisted');fireEvent.change(second.getByLabelText('Text'),{target:{value:'typed'}});assert.equal(window.sessionStorage.getItem('draft-junior'),'typed');fireEvent.click(second.getByText('Clear draft'));assert.equal(second.getByLabelText('Text').value,'');assert.equal(window.sessionStorage.getItem('draft-junior'),null);second.unmount();const proto=window.Storage.prototype;const old=Object.fromEntries(['getItem','setItem','removeItem'].map(k=>[k,proto[k]]));try{for(const k of Object.keys(old))proto[k]=()=>{throw new Error('blocked');};const third=render(React.createElement(Component,{}));const input=within(third.container).getByLabelText('Text');assert.equal(input.value,'');fireEvent.change(input,{target:{value:'still works'}});assert.equal(within(third.container).getByRole('status').textContent,'still works');fireEvent.click(within(third.container).getByRole('button',{name:'Clear draft'}));assert.equal(input.value,'');third.unmount();}finally{Object.assign(proto,old);}`,
{setup:"window.sessionStorage.clear();window.sessionStorage.setItem('draft-junior','preset');"});

add('Memoized filtering / performance variant', 'performance',
`Props items are {id,name,tier}. A Tier select (all/gold/silver) and a Min length number input (nonnegative integer, default 0). Render matching names (exact tier match AND name length >= min) in listitems. Compute the filtered list with useMemo keyed on [items, tier, minLength]; otherwise still correct. Output count. Changing an unrelated rerender prop must not reset either control (state lives in the component, not the list).`,
`const [tier,setTier]=useState('all'),[minLen,setMinLen]=useState('0');const filtered=useMemo(()=>items.filter(x=>(tier==='all'||x.tier===tier)&&x.name.length>=Number(minLen)),[items,tier,minLen]);
return <section><label>Tier<select value={tier} onChange={e=>setTier(e.target.value)}>{['all','gold','silver'].map(x=><option key={x}>{x}</option>)}</select></label><label>Min length<input type="number" min="0" step="1" value={minLen} onChange={e=>setMinLen(e.target.value)}/></label><ul>{filtered.map(x=><li key={x.id}>{x.name}</li>)}</ul><output>{filtered.length}</output></section>;`,
`assert.equal(status(),'4');change('Tier','gold');assert.equal(status(),'2');change('Min length','4');assert.deepEqual(view.getAllByRole('listitem').map(x=>x.textContent),['Golden','Goldenrod']);change('Tier','silver');assert.equal(status(),'1');assert.deepEqual(view.getAllByRole('listitem').map(x=>x.textContent),['Silvery']);view.rerender(React.createElement(Component,{items:props.items,noise:1}));assert.equal(field('Tier').value,'silver');assert.equal(field('Min length').value,'4');view.rerender(React.createElement(Component,{items:[{id:5,name:'Silverware',tier:'silver'}]}));assert.equal(status(),'1');assert.deepEqual(view.getAllByRole('listitem').map(x=>x.textContent),['Silverware']);`,
{params:'{items=[]}',props:{items:[{id:1,name:'Golden',tier:'gold'},{id:2,name:'Silvery',tier:'silver',stars:2},{id:3,name:'Goldenrod',tier:'gold'},{id:4,name:'Tin',tier:'silver'}]}});

add('Lifted state between two panels', 'state',
`Two sibling panels share a single source of truth in the parent: Panel A (aria-label Editor) has a Note input; Panel B (aria-label Preview) mirrors it live. A Clear button (outside panels) empties the note. Character count output says N characters. Test verifies editing in A updates B without local copies drifting. Nothing but lifted state may hold the note.`,
`const [note,setNote]=useState('');
return <section><div role="group" aria-label="Editor"><label>Note<input value={note} onChange={e=>setNote(e.target.value)}/></label></div><div role="group" aria-label="Preview"><output>{note}</output></div><button onClick={()=>setNote('')}>Clear</button><output aria-label="Count">{note.length} characters</output></section>;`,
`change('Note','hello');assert.equal(status('Count'),'5 characters');assert.equal(within(view.getByRole('group',{name:'Preview'})).getByRole('status').textContent,'hello');change('Note','hi!');assert.equal(within(view.getByRole('group',{name:'Preview'})).getByRole('status').textContent,'hi!');click('Clear');assert.equal(field('Note').value,'');assert.equal(status('Count'),'0 characters');`);

add('Independent counters / shared-handler refactor variant', 'debugging / refactoring',
`Refactoring brief: replace three duplicated counter handlers with a shared update function. The starter is blank; build the refactored version. Requirements: one shared behavior, three labelled buttons Bump A, Bump B, Bump C each incrementing only its own count (output Count A/B/C reads n). Reset all zeroes every count. Keep the component short and DRY — tests care about behavior only: independent increments, exact labels, reset all. The reference solution consolidates the logic; you may use any correct structure.`,
`const [counts,setCounts]=useState({A:0,B:0,C:0});const bump=key=>setCounts(c=>({...c,[key]:c[key]+1}));
return <section>{['A','B','C'].map(key=><div key={key}><output aria-label={'Count '+key}>{counts[key]}</output><button aria-label={'Bump '+key} onClick={()=>bump(key)}>Bump {key}</button></div>)}<button onClick={()=>setCounts({A:0,B:0,C:0})}>Reset all</button></section>;`,
`const count=key=>status('Count '+key);click('Bump A');click('Bump A');click('Bump B');assert.equal(count('A'),'2');assert.equal(count('B'),'1');assert.equal(count('C'),'0');click('Bump C');click('Reset all');assert.equal(count('A'),'0');assert.equal(count('B'),'0');assert.equal(count('C'),'0');click('Bump C');assert.equal(count('C'),'1');`);

add('Refactor me: chained conditionals to map', 'debugging / refactoring',
`Refactoring brief (blank starter): replace a long if/else chain mapping status codes to labels (paid -> Payment received, pending -> Awaiting payment, failed -> Payment failed, unknown -> Status unknown). Replace with a data-driven lookup; behavior: uppercase-insensitive input prop status (default 'pending'), output label, and an output detail line CODE:LABEL (no space after colon). Unknown codes (including empty) map to the unknown label.`,
`const labels={paid:'Payment received',pending:'Awaiting payment',failed:'Payment failed'};const label=Object.hasOwn(labels,String(status).toLowerCase())?labels[String(status).toLowerCase()]:'Status unknown';
return <section><output aria-label="Label">{label}</output><output aria-label="Detail">{String(status).toUpperCase()}:{label}</output></section>;`,
`const label=()=>status('Label'),detail=()=>status('Detail');assert.equal(label(),'Awaiting payment');assert.equal(detail(),'PENDING:Awaiting payment');view.rerender(React.createElement(Component,{status:'PAID'}));assert.equal(label(),'Payment received');view.rerender(React.createElement(Component,{status:'failed'}));assert.equal(label(),'Payment failed');view.rerender(React.createElement(Component,{status:'mystery'}));assert.equal(label(),'Status unknown');view.rerender(React.createElement(Component,{status:''}));assert.equal(label(),'Status unknown');view.rerender(React.createElement(Component,{status:'constructor'}));assert.equal(label(),'Status unknown');`,
{params:'{status="pending"}'});

add('Context refactor of nested theme controls','debugging / refactoring',
`Refactoring brief, blank starter: replace theme and toggle props passed through middle layers with module-scope context. Exercise owns light/dark state, a nested leaf group Themed box displays theme in output, and a second leaf Toggle button changes it using context. The middle layer should receive neither theme nor toggle. Initial light. Each mounted Exercise is independent.`,
`const [theme,setTheme]=useState('light');return <ThemeContext.Provider value={{theme,toggle:()=>setTheme(t=>t==='light'?'dark':'light')}}><Middle/></ThemeContext.Provider>;`,
`const leaf=()=>within(view.getByRole('group',{name:'Themed box'})).getByRole('status').textContent;assert.equal(leaf(),'light');click('Toggle');assert.equal(leaf(),'dark');click('Toggle');assert.equal(leaf(),'light');view.unmount();const a=render(React.createElement(Component));const b=render(React.createElement(Component));fireEvent.click(within(a.container).getByRole('button',{name:'Toggle'}));assert.equal(within(a.container).getByRole('status').textContent,'dark');assert.equal(within(b.container).getByRole('status').textContent,'light');`,
{pre:`const ThemeContext=React.createContext(null);function ThemeLeaf(){const {theme}=React.useContext(ThemeContext);return <section role="group" aria-label="Themed box"><output>{theme}</output></section>;}function ToggleLeaf(){const {toggle}=React.useContext(ThemeContext);return <button onClick={toggle}>Toggle</button>;}function Middle(){return <div><ThemeLeaf/><ToggleLeaf/></div>;}`});

add('Trace a missing effect dependency','debugging / effects',
`Debugging brief, blank starter: an effect depending only on query forgets mode. Query input starts empty; Mode select alpha/beta starts alpha. Props fetchCombined(query,mode) resolves a string. Output Result initially/loading while pending, then the resolved string. Fetch when either input or service prop changes. Ignore stale completions; report errors with Result=error and role alert.`,
`const [query,setQuery]=useState(''),[mode,setMode]=useState('alpha'),[result,setResult]=useState('loading'),[error,setError]=useState('');useEffect(()=>{let live=true;setResult('loading');setError('');Promise.resolve().then(()=>fetchCombined(query,mode)).then(value=>{if(live)setResult(value);},e=>{if(live){setResult('error');setError(e.message);}});return()=>{live=false;};},[query,mode,fetchCombined]);return <section><label>Query<input value={query} onChange={e=>setQuery(e.target.value)}/></label><label>Mode<select value={mode} onChange={e=>setMode(e.target.value)}><option>alpha</option><option>beta</option></select></label><output aria-label="Result">{result}</output>{error&&<p role="alert">{error}</p>}</section>;`,
`assert.equal(status('Result'),'loading');await act(async()=>{});assert.equal(status('Result'),'alpha:');change('Query','x');await act(async()=>{});assert.equal(status('Result'),'alpha:x');change('Mode','beta');await act(async()=>{});assert.equal(status('Result'),'beta:x');assert.deepEqual(calls,[['','alpha'],['x','alpha'],['x','beta']]);change('Query','xy');await act(async()=>{});assert.equal(status('Result'),'beta:xy');view.rerender(React.createElement(Component,{fetchCombined:async()=>{throw Error('offline');}}));await act(async()=>{});assert.equal(status('Result'),'error');assert.equal(view.getByRole('alert').textContent,'offline');`,
{params:'{fetchCombined}',setup:"const calls=[];props.fetchCombined=async(q,m)=>{calls.push([q,m]);return m+':'+q;};"});

add('Immutable sorting / debugging variant', 'debugging / immutability',
`Props words is an array. A Sort button must render words sorted ascending WITHOUT mutating the props array (debugging brief: copying must replace an in-place .sort() call; starter is blank) and toggling Sort again restores the original order (original/ascending toggle). Sort button label Sort / Unsort. Output list shows words in current order. props.words must be untouched after all interactions.`,
`const [sorted,setSorted]=useState(false);const shown=sorted?[...words].sort():[...words];
return <section><button onClick={()=>setSorted(s=>!s)}>{sorted?'Unsort':'Sort'}</button><ul>{shown.map((word,i)=><li key={word+'-'+i}>{word}</li>)}</ul></section>;`,
`const items=()=>view.queryAllByRole('listitem').map(x=>x.textContent);assert.deepEqual(items(),['pear','fig','apple']);click('Sort');assert.deepEqual(items(),['apple','fig','pear']);click('Unsort');assert.deepEqual(items(),['pear','fig','apple']);click('Sort');assert.deepEqual(items(),['apple','fig','pear']);assert.deepEqual(props.words,['pear','fig','apple']);`,
{params:'{words=[]}',props:{words:['pear','fig','apple']},setup:'Object.freeze(props.words);'});

add('Fix the lost selection on rerender', 'debugging / state',
`Debugging brief (blank starter): an index-based selection breaks when props reorder. Rebuild with stable ids. Requirement: keep the selection stable across item-list changes as long as the id still exists; if the id disappears, clear the selection (output None). Props items are {id,name}; selection via buttons labelled Pick NAME. Output shows the selected name or None.`,
`const [selected,setSelected]=useState(null);useEffect(()=>{if(selected!==null&&!items.some(x=>x.id===selected))setSelected(null);},[items,selected]);const exists=selected!==null&&items.some(x=>x.id===selected);const current=exists?items.find(x=>x.id===selected).name:null;
return <section>{items.map(x=><button key={x.id} onClick={()=>setSelected(x.id)}>Pick {x.name}</button>)}<output>{selected===null?'None':exists?current:'None'}</output></section>;`,
`assert.equal(status(),'None');click('Pick A');assert.equal(status(),'A');view.rerender(React.createElement(Component,{items:[...props.items].reverse()}));assert.equal(status(),'A');view.rerender(React.createElement(Component,{items:[...props.items,{id:'d',name:'D'}]}));assert.equal(status(),'A');view.rerender(React.createElement(Component,{items:[{id:'b',name:'B'},{id:'d',name:'D'}]}));assert.equal(status(),'None');view.rerender(React.createElement(Component,{items:props.items}));assert.equal(status(),'None');view.rerender(React.createElement(Component,{items:[{id:'d',name:'D'},{id:'b',name:'B'}]}));click('Pick D');view.rerender(React.createElement(Component,{items:[{id:'b',name:'B'},{id:'d',name:'D'}]}));assert.equal(status(),'D');`,
{params:'{items=[]}',props:{items:[{id:'a',name:'A'},{id:'b',name:'B'},{id:'c',name:'C'}]}});

add('Migration: HOC wrapper to hook', 'refactoring',
`Refactoring brief (blank starter): replace a wrapper's fetch logic with a reusable hook. Rebuild as a hook: useUser must (1) return {loading,name,error}, (2) call props.fetchUser once on mount only, and (3) clean up properly. Render: while loading show output loading; on success output with the name; on error role alert with message. Reference behavior given in spec; tests use an already-resolved fetchUser.`,
`const {loading,name,error}=useUser(fetchUser);
return <section><output>{loading?'loading':name}</output>{error&&<p role="alert">{error}</p>}</section>;`,
`assert.equal(status(),'loading');assert.equal(calls,1);await act(async()=>pending[0].resolve({name:'Ada'}));assert.equal(status(),'Ada');view.rerender(React.createElement(Component,{fetchUser:props.fetchUser,noise:1}));assert.equal(calls,1);assert.equal(status(),'Ada');view.unmount();const second=render(React.createElement(Component,{fetchUser:props.fetchUser}));assert.equal(calls,2);await act(async()=>pending[1].reject(new Error('offline')));assert.equal(second.getByRole('alert').textContent,'offline');second.unmount();const third=render(React.createElement(Component,{fetchUser:props.fetchUser}));assert.equal(calls,3);third.unmount();await act(async()=>pending[2].resolve({name:'late'}));assert.equal(document.body.textContent,'');`,
{params:'{fetchUser}',setup:'let calls=0;const pending=[];props.fetchUser=()=>{calls++;return new Promise((resolve,reject)=>pending.push({resolve,reject}));};',pre:`function useUser(fetchUser){const [state,setState]=React.useState({loading:true,name:'',error:null});React.useEffect(()=>{let live=true;fetchUser().then(user=>{if(live)setState({loading:false,name:user.name,error:null});}).catch(e=>{if(live)setState({loading:false,name:'',error:e.message});});return()=>{live=false;};},[]);return state;}\n`});

const START_ID=1369;
const VERSION=1;
if(tasks.length!==50)throw new Error('Expected exactly 50 exercises');
const dirOut=path.join(__dirname,'react-junior');
if(fs.existsSync(dirOut)){
  throw new Error('refusing to overwrite existing '+dirOut+' (delete it first to rebuild)');
}
for(const part of ['starters','solutions','tests'])fs.mkdirSync(path.join(dirOut,part),{recursive:true});
fs.writeFileSync(path.join(dirOut,'clock.cjs'),"'use strict';\nconst names=['setTimeout','clearTimeout','setInterval','clearInterval'];\nconst originals=Object.fromEntries(names.map(k=>[k,globalThis[k]]));\nlet enabled=false,now=0,serial=0;const timers=new Map();\nmodule.exports={\n fn(impl=()=>undefined){const calls=[];const f=(...args)=>{calls.push(args);return impl(...args);};f.mock={calls};return f;},\n useFakeTimers(){if(enabled)return;enabled=true;now=0;serial=0;timers.clear();const schedule=(fn,ms,interval,args)=>{const id=++serial;timers.set(id,{fn,args,at:now+Math.max(1,Number(ms)||0),interval:interval?Math.max(1,Number(ms)||0):0});return id;};globalThis.setTimeout=(fn,ms,...args)=>schedule(fn,ms,false,args);globalThis.setInterval=(fn,ms,...args)=>schedule(fn,ms,true,args);globalThis.clearTimeout=globalThis.clearInterval=id=>timers.delete(id);},\n advanceTimersByTime(ms){if(!enabled)throw Error('Enable fake timers first');const end=now+ms;let steps=0;while(true){let id=null,next=null;for(const [key,timer] of timers)if(timer.at<=end&&(!next||timer.at<next.at)){id=key;next=timer;}if(!next)break;if(++steps>10000)throw Error('Runaway timer');now=next.at;if(next.interval)next.at+=next.interval;else timers.delete(id);next.fn(...next.args);}now=end;},\n getTimerCount(){return timers.size;},\n useRealTimers(){for(const name of names)globalThis[name]=originals[name];timers.clear();enabled=false;}\n};\n");
const manifest=[];
tasks.forEach((task,i)=>{
  const id=START_ID+i;
  const header=`// ${id} ${task.title} [${task.category}]\n// ${task.spec}\n// Run: node react-junior/verify.cjs --id=${id} [--starters]\n`;
  const imports=`import React,{useState,useEffect,useReducer,useRef,useMemo,useLayoutEffect,useId,useContext,createContext} from 'react';\n`;
  const solution=imports+(task.pre||'')+`export default function Exercise(${task.params||'{}'}){${task.code}}\n`;
  const starter=imports+`export default function Exercise(${task.params||'{}'}){return <p>TODO exercise ${id}</p>;}\n`;
  fs.writeFileSync(path.join(dirOut,'solutions',id+'.jsx'),header+solution);
  fs.writeFileSync(path.join(dirOut,'starters',id+'.jsx'),header+starter);
  const test=`const assert=require('node:assert/strict');
const {within}=require('@testing-library/react');
module.exports=async({Component,React,render,fireEvent,act,clock})=>{
const props=${JSON.stringify(task.props||{})};${task.setup||''}
const view=render(React.createElement(Component,props));
const status=(name)=>view.getByRole('status',{name:name===undefined?'':name}).textContent;
const click=n=>fireEvent.click(view.getByRole('button',{name:n}));
const button=n=>view.getByRole('button',{name:n});
const field=n=>view.getByLabelText(n);
const change=(n,v)=>fireEvent.change(field(n),{target:{value:v}});
${task.test}
};
`;
  fs.writeFileSync(path.join(dirOut,'tests',id+'.cjs'),test);
  manifest.push({id,tech:'react',category:task.category,title:task.title,starter:'starters/'+id+'.jsx',solution:'solutions/'+id+'.jsx',test:'tests/'+id+'.cjs'});
});
fs.writeFileSync(path.join(dirOut,'manifest.json'),JSON.stringify(manifest,null,2));
fs.writeFileSync(path.join(dirOut,'verify.cjs'),`'use strict';
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const {JSDOM}=require('jsdom'),esbuild=require('esbuild');
const dom=new JSDOM('<!doctype html><html><body></body></html>',{url:'http://localhost/'});
for(const key of ['window','document','navigator','HTMLElement','HTMLInputElement','Node','Event','KeyboardEvent','MutationObserver'])Object.defineProperty(globalThis,key,{value:dom.window[key],configurable:true});
globalThis.IS_REACT_ACT_ENVIRONMENT=true;
const React=require('react');const rtl=require('@testing-library/react');
const {render,fireEvent,cleanup,act}=rtl;
const originalWindowAdd=window.addEventListener,originalWindowRemove=window.removeEventListener;
const clock=require('./clock.cjs');
const manifest=require('./manifest.json');assert.equal(manifest.length,${tasks.length});assert.equal(new Set(manifest.map(x=>x.id)).size,${tasks.length});
const option=process.argv.find(a=>a.startsWith('--id='));const entries=option?manifest.filter(x=>x.id===Number(option.slice(5))):manifest;
if(!entries.length)throw new Error('Unknown id');const mode=process.argv.includes('--starters')?'starter':'solution';
(async()=>{let passed=0,failed=0;for(const row of entries){try{
 for(const field of ['starter','solution'])await esbuild.transform(fs.readFileSync(path.join(__dirname,row[field]),'utf8'),{loader:'jsx',jsx:'automatic'});
 const result=await esbuild.build({entryPoints:[path.join(__dirname,row[mode])],bundle:true,write:false,platform:'node',format:'cjs',jsx:'automatic',packages:'external',logLevel:'silent'});
 const Module=require('node:module');const m=new Module(path.join(__dirname,'runtime.cjs'),module);m.filename=path.join(__dirname,'runtime.cjs');m.paths=module.paths;m._compile(result.outputFiles[0].text,m.filename);
 await require(path.join(__dirname,row.test))({Component:m.exports.default,React,render,fireEvent,act,clock});passed++;console.log('PASS '+row.id+' '+row.title);
 }catch(e){failed++;console.error('FAIL '+row.id+' '+e.stack);}finally{cleanup();clock.useRealTimers();window.addEventListener=originalWindowAdd;window.removeEventListener=originalWindowRemove;delete navigator.clipboard;window.sessionStorage.clear();document.body.innerHTML='';}}
 console.log(mode+' DOM interaction tests: '+passed+' passed, '+failed+' failed.');dom.window.close();process.exitCode=failed?1:0;
})().catch(e=>{console.error(e);dom.window.close();process.exitCode=1;});
`);
fs.writeFileSync(path.join(dirOut,'GUIDE.txt'),`REACT-JUNIOR\n\n${tasks.length} junior React exercises, ids ${START_ID}..${START_ID+tasks.length-1}. 50 separately specified scenarios; related-pattern variants are explicitly labelled, not claimed as unrelated concepts. Categories: state, forms, CRUD, a11y, effects, async, debugging/refactoring, performance.\n\nFrom unionboot:\n  node react-junior/verify.cjs\n  node react-junior/verify.cjs --starters\n  node react-junior/verify.cjs --id=${START_ID}\n  node react-junior/verify.cjs --starters --id=${START_ID}\n\nEach exercise exports a default component; read the spec comment in the starter and the matching tests/<id>.cjs for props. Tests run in jsdom using real DOM elements, React act, accessible queries and dispatched events. Timer exercises use the local deterministic clock.cjs (not Jest); asynchronous tests inject deferred promises and never access a network. Each test has behavior assertions; structural learning goals such as using a hook, useMemo or context additionally require self-review. No preview server. Blank starters intentionally fail. Debug/refactor prompts describe the legacy mistake rather than supplying a solved starter.\n\n`+manifest.map(x=>x.id+' '+x.title+' ['+x.category+']').join('\n'));
console.log('Created react-junior: '+tasks.length+' exercises (ids '+START_ID+'..'+(START_ID+tasks.length-1)+') with DOM tests');
